class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        from collections import defaultdict
        pos = defaultdict(list)
        for i, v in enumerate(nums):
            pos[v].append(i)
        n = len(nums)
        ans = n
        for idx in pos.values():
            m = len(idx)
            worst = idx[0] + n - idx[-1]
            for k in range(1, m):
                worst = max(worst, idx[k] - idx[k - 1])
            ans = min(ans, worst // 2)
        return ans

