class Solution {
    public int minimumSeconds(List<Integer> nums) {
        Map<Integer, List<Integer>> pos = new HashMap<>();
        int n = nums.size();
        for (int i = 0; i < n; i++)
            pos.computeIfAbsent(nums.get(i), k -> new ArrayList<>()).add(i);
        int ans = n;
        for (List<Integer> idx : pos.values()) {
            int worst = idx.get(0) + n - idx.get(idx.size() - 1);
            for (int k = 1; k < idx.size(); k++)
                worst = Math.max(worst, idx.get(k) - idx.get(k - 1));
            ans = Math.min(ans, worst / 2);
        }
        return ans;
    }
}

