var minimumSeconds = function(nums) {
    const pos = new Map();
    nums.forEach((v, i) => {
        if (!pos.has(v)) pos.set(v, []);
        pos.get(v).push(i);
    });
    const n = nums.length;
    let ans = n;
    for (const idx of pos.values()) {
        let worst = idx[0] + n - idx[idx.length - 1];
        for (let k = 1; k < idx.length; k++)
            worst = Math.max(worst, idx[k] - idx[k - 1]);
        ans = Math.min(ans, Math.floor(worst / 2));
    }
    return ans;
};
